// deploy/examples/datadog: what Integrations → Kubernetes → Install generates (kubernetesSetup.ts) for the in-cluster
// intake, so the examples and the page stay one source. Run after changing kubernetesSetup.ts:
//   node scripts/datadog-examples.mjs
import { writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { EXAMPLE_OPTIONS, datadogOperatorManifest, datadogValues, helmCommands } from '../web/src/pages/integrations/kubernetes/kubernetesSetup.ts';

/** The generated file with our notes after its title comment: how to install it, and where it comes from. */
const withHeader = (content, commands) => {
  const lines = content.split('\n');
  const title = lines.findIndex((l) => !l.startsWith('#'));
  const notes = [
    '#',
    ...commands.map((c) => `#   ${c}`),
    '#',
    `# The intake is the in-cluster service, ${EXAMPLE_OPTIONS.intakeUrl}:`,
    '# replace it everywhere with yours (logs take host:port). With an https intake (through the ingress), drop the',
    '# *_LOGS_NO_SSL variables.',
    '# Generated by scripts/datadog-examples.mjs: Integrations → Kubernetes → Install makes the same for your intake,',
    '# with checkboxes for the optional products.',
  ];
  return [...lines.slice(0, title), ...notes, ...lines.slice(title)].join('\n');
};

/** Repository path → content. */
export function exampleFiles() {
  return {
    'deploy/examples/datadog/values.yaml': withHeader(
      datadogValues(EXAMPLE_OPTIONS),
      helmCommands('datadog').map((c) => c.replace('-f values.yaml', '-f values.yaml --set datadog.clusterName=prod-eu')),
    ),
    'deploy/examples/datadog/datadog-agent.yaml': withHeader(datadogOperatorManifest(EXAMPLE_OPTIONS), helmCommands('datadog-operator')),
  };
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  for (const [path, content] of Object.entries(exampleFiles())) writeFileSync(new URL(`../${path}`, import.meta.url), content);
}
